BEGIN READ ONLY;
SELECT json_build_object('profile','srvf_dp_acceptance_runtime','db',current_database(),'super',r.rolsuper,'bypassrls',r.rolbypassrls,'table',c.relname,'member_of_owner',pg_has_role(r.oid,c.relowner,'MEMBER'),'select',coalesce(json_agg(a.attname ORDER BY a.attnum) FILTER (WHERE has_column_privilege(r.oid,c.oid,a.attnum,'SELECT')),'[]'),'insert',coalesce(json_agg(a.attname ORDER BY a.attnum) FILTER(WHERE has_column_privilege(r.oid,c.oid,a.attnum,'INSERT')),'[]'),'update',coalesce(json_agg(a.attname ORDER BY a.attnum) FILTER(WHERE has_column_privilege(r.oid,c.oid,a.attnum,'UPDATE')),'[]'))
FROM pg_roles r JOIN pg_class c ON c.relname IN ('ActivityParticipationIdentity','ActivityEvidenceState','organization_closure') JOIN pg_namespace ns ON c.relnamespace=ns.oid AND ns.nspname='public' JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped WHERE r.rolname='srvf_dp_acceptance_runtime' GROUP BY r.oid,r.rolsuper,r.rolbypassrls,c.oid,c.relowner,c.relname ORDER BY c.relname;
ROLLBACK;
